import fs from 'node:fs';import assert from 'node:assert/strict';import {gunzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {execFileSync} from 'node:child_process';import {DatabaseSync} from 'node:sqlite';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {collectDiscoveryHealth} from './src/newsFlow/discoveryHealth.mjs';import {NewsRepairPool} from './src/web/newsRepairPool.mjs';import {parseConfiguredArticle} from './src/web/configurableNewsParser.mjs';import {toEs5News} from './src/newsFlow/identity.mjs';import {currentAuditGate} from './scripts/news_current_audit_gate.mjs';
const root='/var/lib/news-flow/qc-alt25-20261122',sha=x=>createHash('sha256').update(x).digest('hex'),registry=await loadNewsRegistry(),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),parsers=new NewsRepairPool(2,new URL('file:///opt/news-flow/current/src/web/newsDeepAuditWorker.mjs')),batch=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-close25-20261122/batch.json')),routes=JSON.parse(fs.readFileSync(root+'/routes.json')),plan=JSON.parse(fs.readFileSync(root+'/parser-patch-plan.json')),r={at:new Date().toISOString(),parserFiles:plan.files.map(p=>({file:p.file,sha256:sha(fs.readFileSync(p.file)),matches:sha(fs.readFileSync(p.file))===p.afterSha})),configUnchanged:batch.sites.map(s=>({site:s.site,unchanged:sha(fs.readFileSync(s.file))===s.fileSha})),cnnNativeReplay:[],restoredSourceControls:[]};
try{
 const source=registry.sources.get('edition.cnn.com'),samples=JSON.parse(fs.readFileSync(root+'/cnn-samples.json')).samples;
 for(const s of samples){const html=gunzipSync(fs.readFileSync(s.file)).toString(),url=s.footer.find(a=>a.text==='See Full Web Article')?.href;assert(url);const config={...source.config,title:{strategy:'selector',selector:'h2.headline'},body:{strategy:'selector',selector:'article.article--lite',removeExtra:'.source--lite'},description:{strategy:'native_lead',scope:'.layout-article-elevate__lite',selector:'article.article--lite > p.paragraph--lite',onlyIfMissing:true},publishedDate:{strategy:'jsonld'},variants:[]},parsed=parseConfiguredArticle(html,url,config),o={transportUrl:s.url,canonicalUrl:url,error:parsed.error||null,publishedDate:parsed._source?.publishedDate,descriptionChars:parsed._source?.description?.length,bodyChars:parsed._source?.content?.length,restricted:parsed.extracted?.publisherRestricted,publicationProof:parsed.extracted?.publicationProof};if(!parsed.error){assert.equal(parsed.extracted.publisherRestricted,true);try{toEs5News(parsed,config);throw Error('RESTRICTED_RECORD_MUST_NOT_WRITE');}catch(e){assert.equal(e.code||e.message,'NEWS_PUBLICATION_OR_ACCESS_UNCONFIRMED');o.esGate=e.code||e.message;}}r.cnnNativeReplay.push(o);}
 const qualified=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-complete27-20261122/qualified-sites.json'));for(const s of qualified.sites.filter(s=>s.approved)){for(const p of s.pages.filter(p=>p.doc)){const html=gunzipSync(fs.readFileSync(p.file)).toString(),v=currentAuditGate(await parsers.run({sample:{domain:s.site,url:p.url,html,kind:'article'},config:s.config,learn:false}),s.config,registry);assert(!v.error&&!v.quality?.length);const doc=toEs5News(v.parsed,s.config,{now:p.doc._source.insertedDate});assert.deepEqual(doc,p.doc);r.restoredSourceControls.push({site:s.site,url:p.url,exactFieldMatch:true});}}
 r.aiUsage=db.prepare('SELECT * FROM ai_usage ORDER BY day').all();r.aiLedgerUnchanged=JSON.stringify(routes.aiUsage)===JSON.stringify(r.aiUsage);r.services=execFileSync('systemctl',['show','news-flow-seed','news-flow-parse','news-flow-import','-p','Id,MainPID,ActiveState,NRestarts'],{encoding:'utf8'});r.cohortAlerts=collectDiscoveryHealth(db,registry.sources.values()).sites.filter(s=>batch.cohort.includes(s.site)).map(s=>({site:s.site,alerts:s.alerts}));assert(r.parserFiles.every(f=>f.matches));assert(r.configUnchanged.every(f=>f.unchanged));assert(r.aiLedgerUnchanged);assert.equal(r.restoredSourceControls.length,10);assert.equal((r.services.match(/ActiveState=active/g)||[]).length,3);assert.equal((r.services.match(/NRestarts=0/g)||[]).length,3);fs.writeFileSync(root+'/final-check.json',JSON.stringify(r,null,2));console.log(JSON.stringify({at:r.at,patchVerified:true,cnnNativeReplay:r.cnnNativeReplay.map(s=>({url:s.canonicalUrl,error:s.error,publishedDate:s.publishedDate,esGate:s.esGate})),controls:r.restoredSourceControls.length,aiLedgerUnchanged:r.aiLedgerUnchanged,services:r.services}));
